const leads = $input.all();

function getValue(item, field) {
  const value = item.json.fields?.[field] ?? item.json[field];

  if (value && typeof value === "object") {
    return value.name ?? value.value ?? "";
  }

  return value ?? "";
}

function normalize(value) {
  return String(value).trim().toUpperCase();
}

const totalProcessed = leads.length;

const reactivationCandidates = leads.filter(item =>
  normalize(getValue(item, "Reactivation Status")) === "QUEUED"
).length;

const skipped = leads.filter(item =>
  normalize(getValue(item, "Reactivation Status")) === "SKIPPED"
).length;

const hot = leads.filter(item =>
  normalize(getValue(item, "Priority")) === "HOT"
).length;

const warm = leads.filter(item =>
  normalize(getValue(item, "Priority")) === "WARM"
).length;

const cold = leads.filter(item =>
  normalize(getValue(item, "Priority")) === "COLD"
).length;

return [{
  json: {
    campaign_status: "COMPLETED",
    total_processed: totalProcessed,
    reactivation_candidates: reactivationCandidates,
    skipped: skipped,
    hot_leads: hot,
    warm_leads: warm,
    cold_leads: cold,
    completed_at: new Date().toISOString()
  }
}];

