const item = $input.first().json;

let body =
  item.textPlain ||
  item.text ||
  item.body ||
  item.snippet ||
  item.html ||
  "";

body = body
  .replace(/<br\s*\/?>/gi, "\n")
  .replace(/<\/p>/gi, "\n")
  .replace(/<[^>]*>/g, "")
  .replace(/&#39;/g, "'")
  .replace(/&apos;/g, "'")
  .replace(/&lt;/g, "<")
  .replace(/&gt;/g, ">")
  .replace(/&amp;/g, "&")
  .trim();

body = body.replace(
  /\s*On\s+(?:Sun|Mon|Tue|Wed|Thu|Fri|Sat),?\s+.+?\s+wrote:\s*[\s\S]*$/i,
  ""
).trim();

// Try common Gmail sender fields
let sender =
  item.from ||
  item.From ||
  item.sender ||
  item.Sender ||
  "";

if (typeof sender === "object") {
  sender =
    sender.email ||
    sender.address ||
    sender.value ||
    "";
}

// Extract email from "Name <email@example.com>"
const emailMatch = String(sender).match(/<([^>]+)>/);

if (emailMatch) {
  sender = emailMatch[1];
}

return [{
  json: {
    customer_reply: body,
    sender_email: String(sender).trim().toLowerCase()
  }
}];

