const parser = $('Switch').first().json.output;

const requestedDate = parser.requested_date;
const requestedTime = parser.requested_time;

if (!requestedDate || !requestedTime) {
  throw new Error(
    `Appointment date/time missing. Date: ${requestedDate}, Time: ${requestedTime}`
  );
}

const now = new Date();

// Convert date
let appointmentDate;

if (requestedDate.toLowerCase() === 'today') {
  appointmentDate = new Date(now);
}

else if (requestedDate.toLowerCase() === 'tomorrow') {
  appointmentDate = new Date(now);
  appointmentDate.setDate(appointmentDate.getDate() + 1);
}

else {
  appointmentDate = new Date(requestedDate);
}

// Convert time
let time = requestedTime
  .toLowerCase()
  .replace(/\s/g, '');

let hours;
let minutes = 0;

const match = time.match(/^(\d{1,2})(?::(\d{2}))?(am|pm)?$/);

if (!match) {
  throw new Error(`Invalid appointment time: ${requestedTime}`);
}

hours = parseInt(match[1]);
minutes = match[2] ? parseInt(match[2]) : 0;

if (match[3] === 'pm' && hours !== 12) {
  hours += 12;
}

if (match[3] === 'am' && hours === 12) {
  hours = 0;
}

appointmentDate.setHours(hours, minutes, 0, 0);

const start = appointmentDate.toISOString();

const endDate = new Date(appointmentDate);
endDate.setMinutes(endDate.getMinutes() + 30);

const end = endDate.toISOString();

return {
  json: {
    ...$json,
    appointment_start: start,
    appointment_end: end,
    appointment_date: requestedDate,
    appointment_time: requestedTime
  }
};

